// Obtenemos los datos estructurados que entrega el agente con el Structured Output Parser
const inputData = $input.item.json;

// Extraemos los campos del esquema unificado
const status = inputData.status || "success";
const servicioInteres = inputData.servicio_interes || "No especificado";
const resumenInteraccion = inputData.resumen_interaccion || "Interacción procesada correctamente";
const preguntaUsuario = inputData.pregunta_usuario || "N/A";
const datosContacto = inputData.datos_contacto || "No proporcionado";
const motivo = inputData.motivo || "N/A";

// Preparamos las variables dinámicas para el asunto y cuerpo del correo
let mailSubject = "";
let mailBody = "";

if (status === "escalated") {
  mailSubject = `[ALERTA CLÍNICA] Duda no resuelta / Requiere especialista`;
  mailBody = `
Atención equipo, se ha detectado una consulta que no pudo ser resuelta por el Agente Recepcionista:

- Motivo del escalamiento: ${motivo}
- Pregunta del usuario: ${preguntaUsuario}
- Datos de contacto: ${datosContacto}
  `.trim();
} else {
  mailSubject = `[LEAD COMERCIAL] Nuevo prospecto interesado en Clínica Larami`;
  mailBody = `
Hola equipo comercial, se ha registrado un nuevo lead exitoso:

- Servicio de interés: ${servicioInteres}
- Resumen de la interacción: ${resumenInteraccion}
  `.trim();
}

// Retornamos las variables preparadas listas para conectarse al nodo de Gmail
return {
  json: {
    status: status,
    subject: mailSubject,
    body: mailBody
  }
};
